#include <vector>

std::vector<int> bowl = {2, 24, 44, 64, 84, 104, 124};

/* 砍一半：每趟先看正中间那一只，答「比了几次」；没找到答负数 */
int half_find(int target) {
    int lo = 0;
    int hi = static_cast<int>(bowl.size()) - 1;
    int tries = 0;

    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        tries++;
        if (bowl[mid] == target) {
            return tries;
        } else if (bowl[mid] < target) {
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }
    return -tries;
}

int main() {
    int want = 124;
    int n = half_find(want);
    if (n < 0) {
        std::cout << "找 " << want << "：没找到\n";
    } else {
        std::cout << "找 " << want << "：比了 " << n << " 次\n";
    }
    return 0;
}

